module asyn_fifo (
    input wclk, rclk, wrstn, rrstn, winc, rinc,
    input [7:0] wdata,
    output wfull, rempty,
    output [7:0] rdata
);

    parameter WIDTH = 8;
    parameter DEPTH = 16;
    // Define ADDR_WIDTH here
    localparam ADDR_WIDTH = $clog2(DEPTH);
    // Define other necessary signals here
    // Write Pointer
    reg [ADDR_WIDTH:0] waddr_bin;
    reg [ADDR_WIDTH:0] wptr;
    reg [ADDR_WIDTH:0] wptr_buff;
    reg [ADDR_WIDTH:0] wptr_syn;
    // Read Pointer
    reg [ADDR_WIDTH:0] raddr_bin;
    reg [ADDR_WIDTH:0] rptr;
    reg [ADDR_WIDTH:0] rptr_buff;
    reg [ADDR_WIDTH:0] rptr_syn;
    // Full and Empty Flags
    reg wfull_reg;
    reg rempty_reg;
    // Connect signals to dual_port_RAM instance
    wire wen, ren;
    wire [ADDR_WIDTH-1:0] waddr, raddr;
    wire [WIDTH-1:0] wdata_ram;
    reg [WIDTH-1:0] rdata_ram;
    // Write Enable Signal
    assign wen = (winc && !wfull);
    // Read Enable Signal
    assign ren = (rinc && !rempty);
    // Address for Writing Data
    assign waddr = waddr_bin[ADDR_WIDTH-1:0];
    // Address for Reading Data
    assign raddr = raddr_bin[ADDR_WIDTH-1:0];
    // Write Data Input
    assign wdata_ram = wdata;
    // Read Data Output
    assign rdata = rdata_ram;
    // Write Pointer Logic
    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            waddr_bin <= 0;
            wptr <= 0;
        end else begin
            if (winc && !wfull) begin
                waddr_bin <= waddr_bin + 1;
                wptr <= {wptr[ADDR_WIDTH-1:0], ~^wptr[ADDR_WIDTH-1:0]};
            end
        end
    end
    // Read Pointer Logic
    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            raddr_bin <= 0;
            rptr <= 0;
        end else begin
            if (rinc && !rempty) begin
                raddr_bin <= raddr_bin + 1;
                rptr <= {rptr[ADDR_WIDTH-1:0], ~^rptr[ADDR_WIDTH-1:0]};
            end
        end
    end
    // Buffer Registers for Write Pointer
    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            wptr_buff <= 0;
        end else begin
            wptr_buff <= wptr;
        end
    end
    // Buffer Registers for Read Pointer
    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            rptr_buff <= 0;
        end else begin
            rptr_buff <= rptr;
        end
    end
    // Synchronize Read Pointer
    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            rptr_syn <= 0;
        end else begin
            rptr_syn <= rptr_buff;
        end
    end
    // Full Flag Logic
    assign wfull = ({~wptr[ADDR_WIDTH:ADDR_WIDTH-1], wptr[ADDR_WIDTH-2:0]} == rptr_syn);
    // Empty Flag Logic
    assign rempty = (rptr_syn == wptr);
    // Update wfull and rempty
    always @(posedge wclk or negedge wrstn) begin
        if (!wrstn) begin
            wfull_reg <= 0;
        end else begin
            wfull_reg <= wfull;
        end
    end
    always @(posedge rclk or negedge rrstn) begin
        if (!rrstn) begin
            rempty_reg <= 0;
        end else begin
            rempty_reg <= rempty;
        end
    end
    // Assign wfull and rempty
    assign wfull = wfull_reg;
    assign rempty = rempty_reg;
    // Instantiate dual_port_RAM
    dual_port_RAM ram (
        .wclk(wclk),
        .rclk(rclk),
        .wen(wen),
        .ren(ren),
        .waddr(waddr),
        .raddr(raddr),
        .wdata(wdata_ram),
        .rdata(rdata_ram)
    );
endmodule
// Helper module for dual-port RAM
module dual_port_RAM (
    input wclk, rclk, wen, ren,
    input [ADDR_WIDTH-1:0] waddr, raddr,
    input [WIDTH-1:0] wdata,
    output reg [WIDTH-1:0] rdata
);
    // Memory Array
    reg [WIDTH-1:0] RAM_MEM [0:DEPTH-1];
    // Write Operation
    always @(posedge wclk) begin
        if (wen) begin
            RAM_MEM[waddr] <= wdata;
        end
    end
    // Read Operation
    always @(posedge rclk) begin
        if (ren) begin
            rdata <= RAM_MEM[raddr];
        end
    end
endmodule
